// src/pages/CursoDetalle.js
import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";

function CursoDetalle() {
  const { id } = useParams(); // Obtener ID del curso desde la URL
  const navigate = useNavigate();
  const [curso, setCurso] = useState(null);
  const [formData, setFormData] = useState({
    nombre: "",
    email: "",
    telefono: "",
    edad: "",
    ocupacion: ""
  });

  useEffect(() => {
    // Obtener detalles del curso desde el backend
    fetch(`http://localhost:3001/api/cursos/${id}`)
      .then((response) => response.json())
      .then((data) => setCurso(data))
      .catch((error) => console.error("Error al obtener el curso:", error));
  }, [id]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      // Enviar inscripción al backend
      const response = await fetch("http://localhost:3001/api/usuarios/inscribirse", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...formData, cursoId: id })
      });

      const data = await response.json();

      if (response.ok) {
        alert("¡Inscripción exitosa! Redirigiendo a pago...");
        // Crear orden de pago en el backend
        const paymentResponse = await fetch("http://localhost:3001/api/pagos/realizar", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            inscripcionId: data.inscripcion.id, // ID de la inscripción
            metodo: "paypal",
            totalAmount: curso.precio // Tomamos el precio del curso
          })
        });

        const paymentData = await paymentResponse.json();
        if (paymentResponse.ok) {
          // Redirigir a PayPal
          window.location.href = `https://www.paypal.com/checkoutnow?token=${paymentData.id}`;
        } else {
          alert("Error al generar pago");
        }
      } else {
        alert("Error en la inscripción");
      }
    } catch (error) {
      console.error("Error al conectar con el servidor:", error);
    }
  };

  if (!curso) return <p>Cargando curso...</p>;

  return (
    <div>
      <h2>{curso.nombre}</h2>
      <p>{curso.descripcion}</p>
      <p>Precio: ${curso.precio}</p>

      <h3>Inscribirse</h3>
      <form onSubmit={handleSubmit}>
        <input type="text" name="nombre" placeholder="Nombre" onChange={handleChange} required />
        <input type="email" name="email" placeholder="Email" onChange={handleChange} required />
        <input type="text" name="telefono" placeholder="Teléfono" onChange={handleChange} required />
        <input type="number" name="edad" placeholder="Edad" onChange={handleChange} required />
        <input type="text" name="ocupacion" placeholder="Ocupación" onChange={handleChange} required />
        <button type="submit">Inscribirse y Pagar</button>
      </form>
    </div>
  );
}

export default CursoDetalle;
